/* THE CHART: one component, two marks.
 *
 * <BarChart> and <LineChart> were separate components and were folded into this
 * one on 2026-08-30, when the owner pointed at how many components in here do
 * the same job under different names. What made them one thing was never the mark: the scale, the
 * grid, the goal line, the readout, the row of labels and the legend are the
 * same furniture on every chart in this system, they live in src/lib/chart.css,
 * and both components rendered exactly those classes around a plot of their
 * own. What is left here is the two MARKS, and the root recipe they share.
 *
 * The root is written once. It was written twice, identically apart from the
 * per-element custom properties each mark sets from the data — which is what a
 * duplicate looks like when it is spread over two files nobody opens together.
 */
.chart {
  /* The three heights a chart is read at, and the width the scale column
   * reserves. */
  --chart-height: calc(var(--space-16) * 1.75);
  --chart-scale-width: 2.5rem;

  /* Set per element from the data, and declared here so the stylesheet stands
   * on its own: a mark with no value has no length, and that is not a crash. */
  --tick-at: 0%;
  --bar-size: 0%;
  --bar-delay: 0ms;
  --readout-at: 50%;
  --dot-x: 0%;
  --dot-y: 0%;

  display: flex;
  flex-direction: column;
  gap: var(--space-3);
  margin: 0;
  min-inline-size: 0;
}
.chart[data-size="sm"] { --chart-height: var(--space-16); }
.chart[data-size="lg"] { --chart-height: calc(var(--space-16) * 2.5); }
/* The bar's own cap, and the column a horizontal chart gives its names. */
.chart[data-type='bar'] { --chart-bar-width: 2.5rem; }

/* ── The BAR mark ───────────────────────────────────────────────────────── */
.chart-bar-plot {
  position: relative;
  flex: 1 1 auto;
  display: flex;
  align-items: flex-end;
  gap: var(--space-2);
  block-size: 100%;
  min-inline-size: 0;
}

/* THE COLUMN IS THE HIT AREA, and it is a button so a keyboard reaches the
 * same readout the pointer does. */
.chart-bar-column {
  position: relative;
  flex: 1 1 0;
  min-inline-size: 0;
  block-size: 100%;
  display: flex;
  align-items: flex-end;
  background: none;
  color: inherit;
  /* Reads, does not navigate: the data cursor, not the link one. */
  cursor: crosshair;
}
.chart-bar-column:focus-visible {
  outline: var(--focus-ring);
  outline-offset: var(--ring-offset);
  border-radius: var(--radius-sm);
}

.chart-bar-bars {
  display: flex;
  align-items: flex-end;
  justify-content: center;
  /* 2px between adjacent fills, so two bars of the same colour still read as
   * two bars. Same gap the stacked segments use. */
  gap: var(--space-2xs);
  inline-size: 100%;
  block-size: 100%;
}
.chart[data-type='bar'][data-stacked] .chart-bar-bars { flex-direction: column-reverse; align-items: center; }

.chart-bar-bar {
  position: relative;
  inline-size: min(100%, var(--chart-bar-width));
  block-size: var(--bar-size);
  min-block-size: var(--space-2xs);
  border-radius: var(--radius-sm) var(--radius-sm) 0 0;
  background: var(--chart-1);
  /* The bar grows out of the baseline it is measured from, one after another
   * across the chart. `both` holds it at zero through its own delay. */
  transform-origin: bottom;
  animation: chart-bar-grow var(--duration-slow) var(--ease-out) var(--bar-delay) both;
}
.chart[data-type='bar'][data-stacked] .chart-bar-bar { border-radius: var(--radius-sm); }

@keyframes chart-bar-grow {
  from { transform: scaleY(0); }
  to   { transform: scaleY(1); }
}

/* THE SERIES SLOTS, in fixed order. A chart with one series paints slot 1, so a
 * single-measure chart is the brand's own colour. */
.chart-bar-bar[data-series="2"] { background: var(--chart-2); }
.chart-bar-bar[data-series="3"] { background: var(--chart-3); }
.chart-bar-bar[data-series="4"] { background: var(--chart-4); }
.chart-bar-bar[data-series="5"] { background: var(--chart-5); }
.chart-bar-bar[data-series="6"] { background: var(--chart-6); }
/* A series that MEANS a status takes the status colour instead of its slot. */
.chart-bar-bar[data-tone="success"] { background: var(--chart-success); }
.chart-bar-bar[data-tone="warning"] { background: var(--chart-warning); }
.chart-bar-bar[data-tone="danger"]  { background: var(--chart-danger); }

/* The whole chart in one status tone, for a single-series chart that is about
 * one thing being good or bad. */
.chart[data-type='bar'][data-tone="neutral"] .chart-bar-bar[data-series="1"] { background: var(--foreground); }
.chart[data-type='bar'][data-tone="success"] .chart-bar-bar[data-series="1"] { background: var(--chart-success); }
.chart[data-type='bar'][data-tone="warning"] .chart-bar-bar[data-series="1"] { background: var(--chart-warning); }
.chart[data-type='bar'][data-tone="danger"]  .chart-bar-bar[data-series="1"] { background: var(--chart-danger); }

/* ONE COLUMN UNDER DISCUSSION: the rest step back rather than the accent
 * shouting. Only when the caller actually named one — `:has` keeps that
 * conditional in the stylesheet instead of an attribute on the figure. */
.chart[data-type='bar']:has(.chart-bar-bar[data-emphasis]) .chart-bar-bar:not([data-emphasis]) { opacity: 0.4; }
/* And the column under the pointer is the one being read. */
.chart[data-type='bar']:has(.chart-bar-column[data-active]) .chart-bar-column:not([data-active]) .chart-bar-bar { opacity: 0.55; }
/* It is never the dim one. The `:has` here is not decoration: the emphasis rule
 * above scores (0,5,0) and a plain descendant version of this one scored
 * (0,4,0), so with an emphasis set, hovering any OTHER column left the bar
 * being read at 0.4 while its neighbours sat at 0.55 — the one bar the reader
 * asked about was the palest thing on the chart. */
.chart[data-type='bar']:has(.chart-bar-column[data-active]) .chart-bar-column[data-active] .chart-bar-bar { opacity: 1; }

.chart-bar-value {
  position: absolute;
  inset-block-end: 100%;
  inset-inline: 0;
  padding-block-end: var(--space-1);
  text-align: center;
  font-size: var(--font-xs);
  color: var(--chart-axis);
  font-variant-numeric: tabular-nums;
}

/* ── LYING DOWN ───────────────────────────────────────────────────────────────
 * The same chart for a RANKING: long names read better beside their bar than
 * rotated under it, and the eye compares lengths down a column. */
.chart[data-type='bar'][data-orientation="horizontal"] .chart-frame { display: block; block-size: auto; }
.chart[data-type='bar'][data-orientation="horizontal"] .chart-bar-plot {
  flex-direction: column;
  align-items: stretch;
  block-size: auto;
  gap: var(--space-3);
}
.chart[data-type='bar'][data-orientation="horizontal"] .chart-bar-column {
  block-size: auto;
  flex-direction: column;
  align-items: stretch;
  gap: var(--space-1);
}
/* Name on the left of its own line, value on the right, bar underneath across
 * the whole width. */
.chart-bar-head {
  display: flex;
  align-items: baseline;
  gap: var(--space-2);
  font-size: var(--font-xs);
  color: var(--chart-axis);
}
.chart-bar-head-value {
  margin-inline-start: auto;
  color: var(--foreground);
  font-variant-numeric: tabular-nums;
}
.chart[data-type='bar'][data-orientation="horizontal"] .chart-bar-bars {
  flex-direction: column;
  align-items: stretch;
  justify-content: center;
  block-size: auto;
}
.chart[data-type='bar'][data-orientation="horizontal"] .chart-bar-bar {
  inline-size: var(--bar-size);
  block-size: var(--space-3);
  min-inline-size: var(--space-2xs);
  /* BOTH ENDS ROUNDED, lying down. Standing up, a bar's foot sits ON the zero
   * line the grid draws, so a square foot reads as anchored; lying down there
   * is no line at the start and a square end reads as a bar somebody cut off
   * (owner, 23.08). */
  border-radius: var(--radius-full);
  transform-origin: inline-start;
  animation-name: chart-bar-grow-inline;
}
@keyframes chart-bar-grow-inline {
  from { transform: scaleX(0); }
  to   { transform: scaleX(1); }
}
.chart-bar-name {
  min-inline-size: 0;
  text-align: start;
  overflow: hidden;
  text-overflow: ellipsis;
  white-space: nowrap;
}
/* THE VALUE AXIS TURNED WITH THE BARS AND ITS LABELS DID NOT. `.chart-scale` is
 * a vertical strip: every tick is placed by `--tick-at` DOWN its side, which is
 * right standing up and puts all of them on one spot lying down — "80" printed
 * over "40" over "20" over "0" in a 2.5rem column beside the first bar
 * (2026-08-29). Lying down the scale is a strip ACROSS the top of the plot, and
 * each tick is offset along it instead of down it. The grid lines below already
 * turned; only the numbers naming them did not. */
.chart[data-type='bar'][data-orientation="horizontal"] .chart-scale {
  inline-size: auto;
  block-size: 1.25em;
  margin-block-end: var(--space-1);
}
.chart[data-type='bar'][data-orientation="horizontal"] .chart-tick {
  inset-inline-end: auto;
  inset-inline-start: var(--tick-at);
  inset-block-end: 0;
  transform: translateX(-50%);
}
.chart[data-type='bar'][data-orientation="horizontal"]:dir(rtl) .chart-tick { transform: translateX(50%); }

.chart[data-type='bar'][data-orientation="horizontal"] .chart-grid {
  inset-block: 0;
  inset-inline: auto;
  inset-inline-start: var(--tick-at);
  border-block-start: 0;
  border-inline-start: 1px solid var(--chart-grid);
}

/* In a card the chart takes the spare height. Cards in a row are the same
 * height (owner's rule, 23.08), so a card whose subject is a chart gets extra
 * room — and the honest place for it is the plot, not a band of white between
 * the plot and the footer. Its own height stays the floor. Written once for
 * both marks: it was the same four declarations in both stylesheets. */
.card > .chart { flex: 1 1 auto; }
.card > .chart .chart-frame {
  block-size: auto;
  min-block-size: var(--chart-height);
  flex: 1 1 auto;
}
/* Lying down there is no plot height to grow into, so the spare room goes
 * BETWEEN the rows: three bars stacked at the top of a card with 100px of
 * white under them is the hole this rule closes. */
.card > .chart[data-type='bar'][data-orientation="horizontal"] .chart-frame { min-block-size: 0; }
.card > .chart[data-type='bar'][data-orientation="horizontal"] .chart-bar-plot {
  block-size: 100%;
  justify-content: space-evenly;
}

/* ── The LINE mark ──────────────────────────────────────────────────────── */
.chart-line-plot {
  position: relative;
  flex: 1 1 auto;
  block-size: 100%;
  min-inline-size: 0;
  /* The whole plot is the hit area for the crosshair: a reader should not have
   * to find a 6px dot to be told what it says. */
  touch-action: none;
  cursor: crosshair;
}
.chart-line-plot > svg { display: block; inline-size: 100%; block-size: 100%; overflow: visible; }

/* THE LINE. 2px, round joins, and the plot wipes itself in once: the shape
 * arriving left to right is the same gesture the reader makes reading it.
 *
 * A WIPE, not a dash. The obvious way to draw a line on is a dash offset, and
 * it does not survive this SVG: `preserveAspectRatio="none"` stretches the
 * viewBox, `vector-effect: non-scaling-stroke` takes the stroke back out of
 * that stretch, and the dash pattern ends up measured in one space and drawn in
 * the other — the line came out in fragments with gaps between the months
 * (measured 23.08, both with a percentage dash and with pathLength="1"). A clip
 * on the plot is geometry the stretch does not touch. */
.chart-line-plot > svg {
  animation: chart-line-wipe var(--duration-slow) var(--ease-out) both;
}
@keyframes chart-line-wipe {
  from { clip-path: inset(0 100% 0 0); }
  to   { clip-path: inset(0); }
}
/* Right to left, the axis reads right to left, and so does the wipe. */
[dir="rtl"] .chart-line-plot > svg {
  transform: scaleX(-1);
  animation-name: chart-line-wipe-rtl;
}
@keyframes chart-line-wipe-rtl {
  from { clip-path: inset(0 0 0 100%); }
  to   { clip-path: inset(0); }
}

.chart-line-line {
  fill: none;
  stroke: var(--chart-1);
  stroke-width: 2;
  stroke-linecap: round;
  stroke-linejoin: round;
}
.chart-line-area {
  fill: var(--chart-1);
  opacity: 0.12;
}

/* THE SERIES SLOTS, in fixed order — never cycled, so a filter that drops a
 * line leaves the others the colour they were. */
.chart-line-series[data-series="2"] .chart-line-line { stroke: var(--chart-2); }
.chart-line-series[data-series="3"] .chart-line-line { stroke: var(--chart-3); }
.chart-line-series[data-series="4"] .chart-line-line { stroke: var(--chart-4); }
.chart-line-series[data-series="5"] .chart-line-line { stroke: var(--chart-5); }
.chart-line-series[data-series="6"] .chart-line-line { stroke: var(--chart-6); }
.chart-line-series[data-tone="success"] .chart-line-line { stroke: var(--chart-success); }
.chart-line-series[data-tone="warning"] .chart-line-line { stroke: var(--chart-warning); }
.chart-line-series[data-tone="danger"]  .chart-line-line { stroke: var(--chart-danger); }

/* THE CROSSHAIR AND ITS DOTS. One vertical rule, one dot per series, so every
 * line is read at the same x. */
.chart-line-crosshair {
  position: absolute;
  inset-block: 0;
  inset-inline-start: var(--dot-x);
  inline-size: 1px;
  background: var(--chart-grid);
  pointer-events: none;
}
.chart-line-dot {
  position: absolute;
  inset-inline-start: var(--dot-x);
  inset-block-start: var(--dot-y);
  inline-size: var(--space-2);
  block-size: var(--space-2);
  margin-inline-start: calc(var(--space-2) / -2);
  margin-block-start: calc(var(--space-2) / -2);
  border-radius: var(--radius-full);
  background: var(--chart-1);
  /* A ring in the surface colour, so a dot that lands on a grid line or on
   * another series still reads as one mark. */
  box-shadow: 0 0 0 var(--space-2xs) var(--card);
  pointer-events: none;
}
.chart-line-dot[data-series="2"] { background: var(--chart-2); }
.chart-line-dot[data-series="3"] { background: var(--chart-3); }
.chart-line-dot[data-series="4"] { background: var(--chart-4); }
.chart-line-dot[data-series="5"] { background: var(--chart-5); }
.chart-line-dot[data-series="6"] { background: var(--chart-6); }
.chart-line-dot[data-tone="success"] { background: var(--chart-success); }
.chart-line-dot[data-tone="warning"] { background: var(--chart-warning); }
.chart-line-dot[data-tone="danger"]  { background: var(--chart-danger); }

/* The ends of a line are POINTS, not the middles of columns: the first and last
 * labels sit under them rather than over a slot that is not there. */
.chart[data-type='line'] .chart-labels > span:first-child { text-align: start; }
.chart[data-type='line'] .chart-labels > span:last-child { text-align: end; }

/* MONOLITHIC BECAUSE THESE ARE A DATA SPECIFICATION, NOT OPTIONS.
 *
 * `series`, `labels`, `type`, `stacked`, `orientation`, `max`, `target`,
 * `emphasis` and `axis` describe one thing: what is being plotted and against
 * what. They arrive together from the caller's data and are meaningless apart —
 * a `stacked` with no `series` says nothing, an `axis` without a `max` cannot be
 * drawn. A compound would ask the caller to spread one object across five
 * elements and then keep them in step by hand.
 *
 * What the split would cost: the chart would have to reconcile children that can
 * contradict each other, which is a whole class of error it does not have today.
 * (2026-09-03)
 */
import '../../lib/chart.css'
import './Chart.css'
import { type CSSProperties, type PointerEvent, useRef, useState } from 'react'
import { cn } from '../lib/cn'
import { areaPath, formatValue, linePath, scaleFor } from '../lib/chart'

type Tone = 'neutral' | 'primary' | 'success' | 'warning' | 'danger'
type Size = 'sm' | 'md' | 'lg'

export type ChartSeries = {
  /** What this measure is. It names the colour in the legend, in the readout
   *  and in the table a screen reader is given. */
  label: string
  /** One value per entry of `labels`, in the same order. */
  values: number[]
  /** A status tone instead of the next series colour — for a measure that MEANS
   *  late, over budget, or done. Otherwise the slot colour, in fixed order. */
  tone?: Extract<Tone, 'success' | 'warning' | 'danger'>
}

type Props = {
  /** Which mark carries the data: `bar` for a value per category, `line` for a
   *  value over time. Everything else on this component is the same furniture. */
  type?: 'bar' | 'line'
  /** The categories, or the x axis oldest first: months, weeks, sites. */
  labels: string[]
  /** One entry per measure. Two or more bring a legend with them. */
  series: ChartSeries[]
  /** `bar`: segments of one column instead of columns side by side, for parts
   *  of a whole per period. Ignored with one series. */
  stacked?: boolean
  /** `bar`: bars run across instead of up. The answer for long category names
   *  and for a ranking, where the eye compares lengths down a column. */
  orientation?: 'horizontal' | 'vertical'
  /** `line`: fills under the line. For ONE series only — two filled areas
   *  overlapping is a chart nobody can read. */
  area?: boolean
  /** Top of the scale. Defaults to the first nice number above the data; pass
   *  it when several charts must share one scale. */
  max?: number
  /** A goal drawn across the plot, so a value can be short OF something. Its
   *  own label is deliberately not a prop: a word printed inside the plot sits
   *  on the data (owner, 23.08). Name the goal in the card's meta line. */
  target?: number
  /** `bar`: the one category that carries the accent — the current period, the
   *  site under discussion. Single-series only; the others stay quiet. */
  emphasis?: string
  /** What the whole measure MEANS, from the metric and not the numbers:
   *  findings closed rising is `success`, incidents rising is `danger`, and the
   *  same marks carry both. */
  tone?: Tone
  /** How much of the page the chart is worth: `md` when it is the block, `sm`
   *  when it is one card in a grid of them. */
  size?: Size
  /** The scale down the side, and the grid lines with it. On by default: a mark
   *  with no scale is a shape, and the reader cannot say how big it is. */
  axis?: boolean
  /** `bar`: values printed on every bar. Off by default — the readout under the
   *  pointer says it for the one being read, which is what a reader asks. */
  showValues?: boolean
  /** What the chart measures. Required in practice: it names the chart for a
   *  screen reader, which then reads the table this component renders for it. */
  label?: string
  /** BCP-47 tag for the numbers. Omit to follow the browser. */
  locale?: string
  className?: string
}

/* The line's drawing space. The viewBox is fixed and the SVG stretches to the
 * card; strokes are held even with vector-effect so a wide card does not draw a
 * fat line and a narrow one a thin one. */
const W = 100
const H = 40

/* Which way a bar's readout hangs off its column. Centred over the middle of
 * the plot, and pinned by one edge over the first and last columns, so it never
 * leaves the card it is being read in. */
function side(at: number, count: number): 'start' | 'center' | 'end' {
  if (count < 3) return 'center'
  if (at === 0) return 'start'
  if (at === count - 1) return 'end'
  return 'center'
}

/* "Aug: Closed 52, Open 8" — the column's whole readout as one string, built
 * outside the JSX because a template inside a template inside a map is not
 * something anyone reads twice. */
function readout(category: string, parts: [string, string][]): string {
  const said = parts.map(([name, value]) => (name ? `${name} ${value}` : value)).join(', ')
  return `${category}: ${said}`
}

/**
 * A measure across categories or over time, with the scale that says by how
 * much: `type="bar"` for a value per category, `type="line"` for a value over
 * time. Carries its own scale, grid, goal line, legend and hover readout, and
 * reads as a TABLE to a screen reader.
 *
 * Reach for <Sparkline> when the shape sits beside a number and needs no axis,
 * <DonutChart> for a whole split into named shares, <Meter> for one value
 * against one target, and a <Table> when the numbers are compared exactly
 * rather than at a glance.
 *
 * Copy: labels are the categories' or periods' own names, short enough to sit
 * under a mark without turning. Series names are the things themselves, because
 * a legend of "Series 1" is a legend of nothing. The accessible label says what
 * is being counted and over what.
 */
export function Chart({
  type = 'bar',
  labels,
  series,
  stacked,
  orientation = 'vertical',
  area,
  max,
  target,
  emphasis,
  tone = 'primary',
  size,
  axis = true,
  showValues,
  label,
  locale,
  className,
}: Props) {
  const [at, setAt] = useState<number | null>(null)
  const plotRef = useRef<HTMLDivElement>(null)

  if (!labels.length || !series.length) return null

  const format = (v: number) => formatValue(v, locale)
  const valuesAt = (i: number) => series.map((s) => s.values[i] ?? 0)

  /* Stacked columns are read as their total, so that is what the scale has to
   * hold; everything else is read mark by mark. */
  const peaks = labels.map((_, i) => {
    const row = valuesAt(i)
    return stacked && type === 'bar' ? row.reduce((sum, v) => sum + v, 0) : Math.max(...row)
  })
  const scale = scaleFor([...peaks, ...(max != null ? [max] : []), ...(target != null ? [target] : [])])
  const top = max ?? scale.max
  const ticks = max != null ? scaleFor([max]).ticks : scale.ticks
  const pct = (v: number) => `${Math.max(0, Math.min(100, (v / top) * 100))}%`

  const single = series.length === 1
  /* Derived into named consts rather than written inline in the JSX, because
   * the registry reads `data-x={binding}` and follows the binding to the prop
   * it comes from: a ternary inline resolves to whatever identifier happens to
   * come first, and the generator then holds the CSS to the wrong prop's union
   * (it held [data-orientation] against `type` and refused to build).
   *
   * And the attributes are NOT gated on `type`. A data attribute says what the
   * caller asked for; which mark acts on it is the CSS's business, and every
   * selector that reads them is already qualified by [data-type]. Gating them
   * here made `orientation` unreachable on a line and `area` unreachable on a
   * bar, which is how the registry contract test reads a variant that cannot be
   * rendered — a prop the registry publishes and the component ignores. */
  const areaFilled = area && single
  const keyShape = type === 'line' ? 'dot' : undefined

  const step = labels.length > 1 ? W / (labels.length - 1) : 0
  const pointsOf = (values: number[]) =>
    values.map(
      (v, i) => [labels.length > 1 ? i * step : W / 2, H - (Math.max(0, Math.min(top, v)) / top) * H] as const,
    )
  const atX = `${(Number(at) / Math.max(1, labels.length - 1)) * 100}%`

  /* Which point the pointer is nearest, for a line. One crosshair for every
   * series at once, because the reader is comparing them at that x — not
   * hunting one dot. */
  const track = (e: PointerEvent<HTMLDivElement>) => {
    const box = plotRef.current?.getBoundingClientRect()
    if (!box || box.width === 0) return
    const ratio = (e.clientX - box.left) / box.width
    const flipped = getComputedStyle(plotRef.current as Element).direction === 'rtl' ? 1 - ratio : ratio
    setAt(Math.max(0, Math.min(labels.length - 1, Math.round(flipped * (labels.length - 1)))))
  }

  /* The scale column and the grid behind the marks: identical on both types,
   * which is half of why this is one component. */
  const gridLines = axis
    ? ticks.map((t) => (
        <span key={t} className="chart-grid" style={{ '--tick-at': pct(t) } as CSSProperties} aria-hidden="true" />
      ))
    : null

  return (
    <figure
      className={cn('chart', className)}
      data-type={type}
      data-tone={tone}
      data-size={size}
      data-orientation={orientation}
      data-stacked={stacked && type === 'bar' ? '' : undefined}
      data-axis={axis ? '' : undefined}
      data-area={areaFilled ? '' : undefined}
      onMouseLeave={type === 'bar' ? () => setAt(null) : undefined}
    >
      <div className="chart-frame">
        {axis && (
          <div className="chart-scale" aria-hidden="true">
            {ticks.map((t) => (
              <span key={t} className="chart-tick" style={{ '--tick-at': pct(t) } as CSSProperties}>
                {format(t)}
              </span>
            ))}
          </div>
        )}

        {type === 'bar' ? (
          <div className="chart-bar-plot">
            {gridLines}
            {target != null && (
              <span className="chart-target" style={{ '--tick-at': pct(target) } as CSSProperties} aria-hidden="true" />
            )}

            {labels.map((name, i) => (
              /* A button, not a div with a mouse handler: the readout is
                 reachable by keyboard and announced, and the whole column is
                 the hit area. */
              <button
                type="button"
                key={name}
                className="chart-bar-column"
                data-active={at === i ? '' : undefined}
                aria-label={readout(name, valuesAt(i).map((v, k) => [single ? '' : series[k].label, format(v)]))}
                onMouseEnter={() => setAt(i)}
                onFocus={() => setAt(i)}
                onBlur={() => setAt(null)}
              >
                {/* Lying down, the name sits OVER its own bar rather than in a
                    column beside it: a names column costs the bars a sixth of
                    the card's width, and the bar is the thing being compared
                    (owner, 23.08: why is it not the full width). */}
                {orientation === 'horizontal' && (
                  <span className="chart-bar-head">
                    <span className="chart-bar-name">{name}</span>
                    {showValues && <span className="chart-bar-head-value">{format(valuesAt(i)[0])}</span>}
                  </span>
                )}
                <span className="chart-bar-bars">
                  {valuesAt(i).map((v, k) => (
                    <span
                      key={series[k].label || k}
                      className="chart-bar-bar"
                      data-series={k + 1}
                      data-tone={series[k].tone}
                      data-emphasis={emphasis === name ? '' : undefined}
                      style={{ '--bar-size': pct(v), '--bar-delay': `${i * 40}ms` } as CSSProperties}
                    >
                      {showValues && orientation === 'vertical' && <span className="chart-bar-value">{format(v)}</span>}
                    </span>
                  ))}
                </span>
              </button>
            ))}

            {at != null && (
              <div
                className="chart-readout"
                data-side={side(at, labels.length)}
                style={{ '--readout-at': `${((at + 0.5) / labels.length) * 100}%` } as CSSProperties}
                aria-hidden="true"
              >
                <span className="chart-readout-label">{labels[at]}</span>
                {valuesAt(at).map((v, k) => (
                  <span key={series[k].label || k} className="chart-readout-row">
                    {!single && <span className="chart-key" data-series={k + 1} data-tone={series[k].tone} />}
                    {!single && <span>{series[k].label}</span>}
                    <span className="chart-readout-value">{format(v)}</span>
                  </span>
                ))}
              </div>
            )}
          </div>
        ) : (
          <div className="chart-line-plot" ref={plotRef} onPointerMove={track} onPointerLeave={() => setAt(null)}>
            {gridLines}
            {target != null && (
              <span className="chart-target" style={{ '--tick-at': pct(target) } as CSSProperties} aria-hidden="true" />
            )}

            <svg viewBox={`0 0 ${W} ${H}`} preserveAspectRatio="none" aria-hidden="true" focusable="false">
              {series.map((s, k) => {
                const pts = pointsOf(s.values)
                return (
                  <g key={s.label} className="chart-line-series" data-series={k + 1} data-tone={s.tone}>
                    {areaFilled && <path className="chart-line-area" d={areaPath(pts, H)} />}
                    <path className="chart-line-line" d={linePath(pts)} vectorEffect="non-scaling-stroke" />
                  </g>
                )
              })}
            </svg>

            {/* The dots ride on top as real elements, so stretching the plot
                cannot turn a circle into an ellipse. */}
            {at != null &&
              series.map((s, k) => (
                <span
                  key={s.label}
                  className="chart-line-dot"
                  data-series={k + 1}
                  data-tone={s.tone}
                  style={
                    {
                      '--dot-x': atX,
                      '--dot-y': `${(1 - Math.max(0, Math.min(top, s.values[at] ?? 0)) / top) * 100}%`,
                    } as CSSProperties
                  }
                  aria-hidden="true"
                />
              ))}

            {at != null && (
              <span
                className="chart-line-crosshair"
                style={{ '--dot-x': atX } as CSSProperties}
                aria-hidden="true"
              />
            )}

            {at != null && (
              <div
                className="chart-readout"
                data-side={at > labels.length / 2 ? 'start' : 'end'}
                style={{ '--dot-x': atX } as CSSProperties}
                aria-hidden="true"
              >
                <span className="chart-readout-label">{labels[at]}</span>
                {series.map((s, k) => (
                  <span key={s.label} className="chart-readout-row">
                    <span className="chart-key" data-shape="dot" data-series={k + 1} data-tone={s.tone} />
                    {!single && <span>{s.label}</span>}
                    <span className="chart-readout-value">{format(s.values[at] ?? 0)}</span>
                  </span>
                ))}
              </div>
            )}
          </div>
        )}
      </div>

      {/* Lying down, every bar carries its own name, so the row below would say
          each of them twice. */}
      {!(type === 'bar' && orientation === 'horizontal') && (
        <div className="chart-labels" aria-hidden="true">
          {labels.map((name, i) => (
            <span key={name} data-active={at === i ? '' : undefined}>
              {name}
            </span>
          ))}
        </div>
      )}

      {!single && (
        <ul className="chart-legend" aria-hidden="true">
          {series.map((s, k) => (
            <li key={s.label}>
              <span className="chart-key" data-shape={keyShape} data-series={k + 1} data-tone={s.tone} />
              {s.label}
            </li>
          ))}
        </ul>
      )}

      {/* The data itself, for a screen reader and for anyone who cannot use
          colour: a chart is a rendering of a table, so the table is what is
          announced rather than a sentence somebody wrote about the shape. */}
      <table className="sr-only">
        {label && <caption>{label}</caption>}
        <thead>
          <tr>
            <th scope="col">{type === 'line' ? 'Point' : 'Category'}</th>
            {series.map((s, k) => (
              <th scope="col" key={s.label || k}>
                {s.label || label || 'Value'}
              </th>
            ))}
          </tr>
        </thead>
        <tbody>
          {labels.map((name, i) => (
            <tr key={name}>
              <th scope="row">{name}</th>
              {valuesAt(i).map((v, k) => (
                <td key={series[k].label || k}>{format(v)}</td>
              ))}
            </tr>
          ))}
        </tbody>
      </table>
    </figure>
  )
}
